void SubinterfaceClientProxy::DidFlush(
    const std::vector<int32_t>& in_values) {
#if BUILDFLAG(MOJO_TRACE_ENABLED)
  TRACE_EVENT1(
    "mojom", "Send lite_js_test::mojom::SubinterfaceClient::DidFlush", "input_parameters",
    [&](perfetto::TracedValue context){
      auto dict = std::move(context).WriteDictionary();
      perfetto::WriteIntoTracedValueWithFallback(
           dict.AddItem("values"), in_values,
                        "<value of type const std::vector<int32_t>&>");
   });
#endif

  const bool kExpectsResponse = false;
  const bool kIsSync = false;
  const bool kAllowInterrupt = true;
  const bool is_urgent = false;

  const uint32_t kFlags =
      ((kExpectsResponse) ? mojo::Message::kFlagExpectsResponse : 0) |
      ((kIsSync) ? mojo::Message::kFlagIsSync : 0) |
      ((kAllowInterrupt) ? 0 : mojo::Message::kFlagNoInterrupt) |
      ((is_urgent) ? mojo::Message::kFlagIsUrgent : 0);

  const size_t estimated_payload_size =
    0;
  mojo::Message message(
      std::to_underlying(messages::SubinterfaceClient::kDidFlush), kFlags, estimated_payload_size);
  mojo::internal::MessageFragment<
      ::lite_js_test::mojom::internal::SubinterfaceClient_DidFlush_Params_Data> params(
          message);
  params.Allocate();
  mojo::internal::MessageFragment<
      typename decltype(params->values)::BaseType>
      values_fragment(params.message());
  constexpr const mojo::internal::ContainerValidateParams& values_validate_params =
      mojo::internal::GetArrayValidator<0, false, nullptr>();
  
  mojo::internal::Serialize<mojo::ArrayDataView<int32_t>>(
    in_values,
    values_fragment,
    &values_validate_params);

  params->values.Set(
      values_fragment.is_null() ? nullptr : values_fragment.data());

  
  MOJO_INTERNAL_CHECK_SERIALIZATION(
    mojo::internal::SendValidation::kDefault,
    !(params->values.is_null()),
    mojo::internal::VALIDATION_ERROR_UNEXPECTED_NULL_POINTER,
    "null values in SubinterfaceClient.DidFlush request");

#if defined(ENABLE_IPC_FUZZER)
  message.set_interface_name(SubinterfaceClient::Name_);
  message.set_method_name("DidFlush");
#endif
  // This return value may be ignored as false implies the Connector has
  // encountered an error, which will be visible through other means.
  ::mojo::internal::SendMojoMessage(*receiver_, message);
}

// static
bool SubinterfaceClientStubDispatch::Accept(
    SubinterfaceClient* impl,
    mojo::Message* message) {
  switch (static_cast<messages::SubinterfaceClient>(message->header()->name)) {
    case messages::SubinterfaceClient::kDidFlush: {
      DCHECK(message->is_serialized());
      internal::SubinterfaceClient_DidFlush_Params_Data* params =
          reinterpret_cast<internal::SubinterfaceClient_DidFlush_Params_Data*>(
              message->mutable_payload());
      

      // Validation for SubinterfaceClient.0
      bool success = true;
      std::vector<int32_t> p_values{};
      SubinterfaceClient_DidFlush_ParamsDataView input_data_view(params, message);
      
      if (success && !input_data_view.ReadValues(&p_values))
        success = false;
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            SubinterfaceClient::Name_, 0, false);
        return false;
      }
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->DidFlush(        
        std::move(p_values));
      return true;
    }
  }
  return false;
}

// static
bool SubinterfaceClientStubDispatch::AcceptWithResponder(
    SubinterfaceClient* impl,
    mojo::Message* message,
    std::unique_ptr<mojo::internal::ResponderThunk> responder) {
  [[maybe_unused]] const bool message_is_sync =
      message->has_flag(mojo::Message::kFlagIsSync);
  [[maybe_unused]] const uint64_t request_id = message->request_id();
  switch (static_cast<messages::SubinterfaceClient>(message->header()->name)) {
    case messages::SubinterfaceClient::kDidFlush: {
      break;
    }
  }
  return false;
}
