bool StructTraits<::lite_js_test::mojom::TestStruct::DataView, ::lite_js_test::mojom::TestStructPtr>::Read(
    ::lite_js_test::mojom::TestStruct::DataView input,
    ::lite_js_test::mojom::TestStructPtr* output) {
  bool success = true;
  ::lite_js_test::mojom::TestStructPtr result(::lite_js_test::mojom::TestStruct::New());
  
      if (success)
        result->x = input.x();
      if (success)
        result->y = input.y();
      if (success && !input.ReadZ(&result->z))
        success = false;
  *output = std::move(result);
  return success;
}

// static
bool UnionTraits<::lite_js_test::mojom::TestUnion::DataView, ::lite_js_test::mojom::TestUnionPtr>::Read(
    ::lite_js_test::mojom::TestUnion::DataView input,
    ::lite_js_test::mojom::TestUnionPtr* output) {
  using UnionType = ::lite_js_test::mojom::TestUnion;
  using Tag = UnionType::Tag;

  switch (input.tag()) {
    case Tag::kX: {
      *output = UnionType::NewX(input.x());
      break;
    }
    case Tag::kS: {
      ::lite_js_test::mojom::TestStructPtr result_s{};
      if (!input.ReadS(&result_s))
        return false;

      *output = UnionType::NewS(
          std::move(result_s));
      break;
    }
    default:

      return false;
  }
  return true;
}

